+    let width = usize::from(width).max(1);
+    let digits = file
+        .hunks
+        .iter()
+        .flat_map(|h| &h.lines)
+        .flat_map(|l| [l.old_line, l.new_line])
+        .flatten()
+        .max()
+        .unwrap_or(1)
+        .to_string()
+        .len();
+    let mut out = Vec::new();
